using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Research Agent – uses an AI chat client with web-search & note-taking tools
// ---------------------------------------------------------------------------

var topic = args.Length > 0 ? string.Join(' ', args) : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Build the AI chat client with automatic tool invocation ---------------
IChatClient innerClient = new OpenAI.Chat.ChatClient(
        model: Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini",
        apiKey: Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the OPENAI_API_KEY environment variable."))
    .AsIChatClient();

IChatClient agent = innerClient
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tools -----------------------------------------------------------------
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- Agentic loop via system prompt ----------------------------------------
var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research the provided
    topic using the tools available to you, then produce a clear summary.

    Follow this workflow:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call `SearchAsync` to search the web.
    3. After each search, call `AddNote` to save the key findings with a source.
    4. Once you have gathered enough information, call `GetNotes` to review
       everything you've collected.
    5. Produce a final, well-structured summary with sections and sources.

    Be thorough but concise. Cite sources where possible.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
];

Console.WriteLine("⏳ Agent is working…\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════════════════════════════");

if (notebook.NoteCount > 0)
{
    Console.WriteLine($"\n📝 {notebook.NoteCount} note(s) were collected during research.\n");
}

return;

// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// ===========================================================================
// Tool: Notebook – in-memory note-taking
// ===========================================================================
sealed class Notebook
{
    private readonly List<(string Source, string Content)> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Save a research note with its source. Use this to record key findings.")]
    public string AddNote(
        [Description("Short label identifying the source (URL or title)")] string source,
        [Description("The finding or insight to remember")] string content)
    {
        _notes.Add((source, content));
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes collected yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] ({n.Source})\n{n.Content}"));
    }
}

// ===========================================================================
// Tool: WebSearcher – lightweight Bing / DuckDuckGo / SerpApi wrapper
// ===========================================================================
sealed class WebSearcher
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information. Returns a list of result snippets.")]
    public async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Try SerpApi if key is available, otherwise fall back to DuckDuckGo
        var serpApiKey = Environment.GetEnvironmentVariable("SERPAPI_KEY");
        if (!string.IsNullOrEmpty(serpApiKey))
            return await SearchWithSerpApiAsync(query, serpApiKey);

        return await SearchWithDuckDuckGoAsync(query);
    }

    private static async Task<string> SearchWithSerpApiAsync(string query, string apiKey)
    {
        var url = $"https://serpapi.com/search.json?q={Uri.EscapeDataString(query)}&api_key={apiKey}&num=5";
        using var response = await Http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.CreateAsync(await response.Content.ReadAsStreamAsync());
        var results = doc.RootElement.TryGetProperty("organic_results", out var organic)
            ? organic.EnumerateArray()
                .Take(5)
                .Select(r =>
                {
                    var title = r.TryGetProperty("title", out var t) ? t.GetString() : "";
                    var snippet = r.TryGetProperty("snippet", out var s) ? s.GetString() : "";
                    var link = r.TryGetProperty("link", out var l) ? l.GetString() : "";
                    return $"• {title}\n  {snippet}\n  {link}";
                })
            : [];

        var text = string.Join("\n\n", results);
        return string.IsNullOrWhiteSpace(text) ? "No results found." : text;
    }

    private static async Task<string> SearchWithDuckDuckGoAsync(string query)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
        using var response = await Http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.CreateAsync(await response.Content.ReadAsStreamAsync());
        var root = doc.RootElement;

        var parts = new List<string>();

        if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } absText)
            parts.Add($"Summary: {absText}\nSource: {root.GetProperty("AbstractURL").GetString()}");

        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var t) && t.GetString() is { Length: > 0 } text)
                {
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                    parts.Add($"• {text}\n  {firstUrl}");
                }
            }
        }

        return parts.Count > 0
            ? string.Join("\n\n", parts)
            : "No results found. Try rephrasing the query.";
    }
}

